/* model: GObject with a property and a notify signal */
typedef struct { GObject parent; gboolean classical; } Pm;
static void on_notify(GObject *pm, GParamSpec *ps, gpointer view) {
    gboolean on = pm_composer_enabled(PM(pm));           /* decision */
    gtk_widget_set_sensitive(GTK_WIDGET(view), on);      /* projection */
}
g_signal_connect(pm, "notify::classical", G_CALLBACK(on_notify), composer_row);
